# Generated by manage.py generate_test_cases.
"""Raw-body authentication and retry-safe callback persistence."""

import base64
import hashlib

from django.http import HttpResponse
from google.protobuf.json_format import MessageToJson
from livekit import api

from bloomerp.communication.builtins.conferencing.controller import ConferenceController
from bloomerp.models.communication.conferencing import (
    ConferenceAttendance,
    ConferenceWebhookReceipt,
)
from bloomerp.tests.base import BloomerpViewTestCase, ExpectedResult, RequestScenario
from bloomerp.tests.communication.conferencing.fixtures import CallFixtures


class TestWebhookView(CallFixtures, BloomerpViewTestCase):
    view_name = "conferencing_webhook"

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Reject unsigned or altered events before storing any receipt."""
        return [
            RequestScenario(
                name="Signed join creates attendance",
                method="POST",
                prepare=self.signed_join,
                expected=ExpectedResult(
                    status_code=204, response_validators=self.joined
                ),
            ),
            RequestScenario(
                name="Unsigned join rejected",
                method="POST",
                prepare=self.unsigned_join,
                expected=ExpectedResult(
                    status_code=403, response_validators=self.untouched
                ),
            ),
            RequestScenario(
                name="Modified raw body rejected",
                method="POST",
                prepare=self.tampered_join,
                expected=ExpectedResult(
                    status_code=403, response_validators=self.untouched
                ),
            ),
            RequestScenario(
                name="Foreign instance signature rejected",
                method="POST",
                prepare=self.foreign_signature,
                expected=ExpectedResult(
                    status_code=403, response_validators=self.untouched
                ),
            ),
            RequestScenario(
                name="GET cannot deliver events",
                expected=ExpectedResult(status_code=405),
            ),
        ]

    def signed_join(self, scenario: RequestScenario) -> None:
        """Sign a real provider event after issuing a scoped connection identity."""
        self.prepare_session()
        identity = ConferenceController(self.normal_user).join(self.session.pk)[
            "identity"
        ]
        event = self.connection_event("EV_signed", "participant_joined", identity)
        scenario.data = MessageToJson(event)
        scenario.content_type = "application/webhook+json"
        digest = base64.b64encode(
            hashlib.sha256(scenario.data.encode()).digest()
        ).decode()
        token = (
            api.AccessToken("instance-key", "instance-secret-at-least-32-characters")
            .with_sha256(digest)
            .to_jwt()
        )
        scenario.headers = {"Authorization": token}

    def unsigned_join(self, scenario: RequestScenario) -> None:
        """Omit authentication from an otherwise valid provider event."""
        self.signed_join(scenario)
        scenario.headers = {}

    def tampered_join(self, scenario: RequestScenario) -> None:
        """Change the body without changing its signature hash."""
        self.signed_join(scenario)
        scenario.data += " "

    def foreign_signature(self, scenario: RequestScenario) -> None:
        """Sign with another deployment's credential pair."""
        self.signed_join(scenario)
        digest = base64.b64encode(
            hashlib.sha256(scenario.data.encode()).digest()
        ).decode()
        scenario.headers = {
            "Authorization": api.AccessToken(
                "foreign-key", "foreign-secret-at-least-32-characters"
            )
            .with_sha256(digest)
            .to_jwt()
        }

    def joined(self, response: HttpResponse) -> bool:
        """Confirm callback processing rather than merely accepting the HTTP request."""
        self.session.refresh_from_db()
        return (
            self.session.status == "active"
            and ConferenceAttendance.objects.count() == 1
            and ConferenceWebhookReceipt.objects.get(event_id="EV_signed").status
            == "processed"
        )

    def untouched(self, response: HttpResponse) -> bool:
        """Ensure failed verification leaves no attendance or deduplication artifacts."""
        return (
            not ConferenceAttendance.objects.exists()
            and not ConferenceWebhookReceipt.objects.exists()
        )
